$('#workspace-create-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),r=await api('POST','/workspaces',{slug:f.get('slug'),name:f.get('name')});if(r.status===201){showApp();await renderSidebar()}else $('#join-workspace-error').textContent=r.data.error||'Unable to create'};
